import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

const canvas=document.querySelector('#world');
const scene=new THREE.Scene();
scene.background=new THREE.Color('#a9b5b2');
scene.fog=new THREE.FogExp2('#a9b5b2',0.00155);
const camera=new THREE.PerspectiveCamera(48,innerWidth/innerHeight,.1,1800);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.65));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.16;
scene.add(new THREE.HemisphereLight('#d9e3dd','#726a5c',2.05));
const sun=new THREE.DirectionalLight('#ffe0b0',3.15);sun.position.set(-180,270,120);sun.castShadow=true;sun.shadow.mapSize.set(1536,1536);sun.shadow.camera.left=-230;sun.shadow.camera.right=230;sun.shadow.camera.top=230;sun.shadow.camera.bottom=-230;sun.shadow.bias=-.0002;scene.add(sun);
const mat=(color,roughness=.82,metalness=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness});
const M={ground:mat('#a99d81'),road:mat('#41494a'),roadEdge:mat('#b0a38b'),sidewalk:mat('#b8ad96'),line:mat('#e0d3ae'),grass:mat('#657866'),leaf:mat('#4b705b'),leaf2:mat('#688267'),trunk:mat('#584a39'),water:mat('#376f78',.28,.2),skin:mat('#ad795e'),white:mat('#e3daca'),dark:mat('#253332'),glass:mat('#8caeac',.26,.3),gold:mat('#caa875',.55,.18),brick:mat('#ac765b'),concrete:mat('#bcad91'),plaster:mat('#d1c5a6'),teal:mat('#789b91'),blue:mat('#596f83'),red:mat('#a95440'),yellow:mat('#d3ae63')};
const boxGeo=new THREE.BoxGeometry(1,1,1),sphereGeo=new THREE.SphereGeometry(1,10,8),cylGeo=new THREE.CylinderGeometry(1,1,1,10),coneGeo=new THREE.ConeGeometry(1,1,8);
const box=(parent,x,y,z,sx,sy,sz,material,cast=true)=>{const o=new THREE.Mesh(boxGeo,material);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=cast;o.receiveShadow=true;parent.add(o);return o;};
const cylinder=(parent,x,y,z,r,h,material,segments=10)=>{const o=new THREE.Mesh(new THREE.CylinderGeometry(r*.88,r,h,segments),material);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;};
const plane=(parent,x,y,z,sx,sz,material)=>{const o=new THREE.Mesh(new THREE.PlaneGeometry(sx,sz),material);o.rotation.x=-Math.PI/2;o.position.set(x,y,z);o.receiveShadow=true;parent.add(o);return o;};
const group=(parent,x=0,y=0,z=0)=>{const g=new THREE.Group();g.position.set(x,y,z);parent.add(g);return g;};
const rand=(a,b)=>a+Math.random()*(b-a);const choose=a=>a[Math.floor(Math.random()*a.length)];
const districts=[
 {name:'Agrabad',x:-190,z:-95,lat:'22.325° N',kind:'business',note:'Port-city ambition, reaching for the clouds.',desc:'PORT CITY BUSINESS DISTRICT'},
 {name:'GEC Circle',x:0,z:0,lat:'22.359° N',kind:'commercial',note:'The city meets here. Then it keeps going.',desc:'THE CITY’S BUSY HEART'},
 {name:'Chawkbazar',x:112,z:112,lat:'22.354° N',kind:'market',note:'A hundred small errands make one big story.',desc:'OLD TOWN, OPEN DOORS'},
 {name:'Muradpur',x:133,z:-116,lat:'22.367° N',kind:'residential',note:'School bells, tea breaks, and the way back.',desc:'LIFE BETWEEN THE HILLS'},
 {name:'Patenga',x:-129,z:300,lat:'22.246° N',kind:'coast',note:'Stay for one more minute. Watch the tide.',desc:'WHERE THE CITY MEETS THE BAY'}
];
const city=group(scene);plane(city,0,-.18,65,950,1100,M.ground);
// Green verges and linked boulevards tie the neighborhoods together.
const roadSegments=[];function road(a,b,width=17){const dx=b.x-a.x,dz=b.z-a.z,len=Math.hypot(dx,dz),angle=Math.atan2(dx,dz);const g=group(city,(a.x+b.x)/2,.015,(a.z+b.z)/2);const slab=box(g,0,0,0,width,.12,len,M.road,false);slab.rotation.y=angle;roadSegments.push({a,b,width});}
for(let i=0;i<districts.length;i++)for(let j=i+1;j<districts.length;j++)if(Math.hypot(districts[i].x-districts[j].x,districts[i].z-districts[j].z)<270)road(districts[i],districts[j],i===1||j===1?18:13);
// Beach, sea wall and a gently patterned bay.
plane(city,-145,-.1,438,1000,430,M.water);plane(city,-145,.015,353,760,13,M.roadEdge);plane(city,-145,.04,344,760,2,M.line);
for(let i=0;i<26;i++){const x=-560+i*33;const wave=box(city,x,.008,rand(390,590),rand(7,22),.012,rand(.22,.6),mat('#85a6a0',.32),false);wave.rotation.y=rand(-.16,.16)}
// One recognizable district center, each with its own small street grid and architecture.
function localRoad(x,z,len,vertical=true,width=8){const r=box(city,x,.045,z,width,.09,len,M.road,false);if(!vertical)r.rotation.y=Math.PI/2;box(city,x,.07,z,width+1,.05,len+1,M.roadEdge,false);r.position.y=.075;}
function sidewalkStrip(x,z,w,d){box(city,x,.11,z,w,.16,d,M.sidewalk,false)}
function windowsFor(g,w,h,d,floors,kind){const cols=Math.max(2,Math.floor(w/(kind==='business'?5:4.2)));for(let floor=0;floor<floors;floor++){const yy=.7+floor*3.1;for(let c=0;c<cols;c++){const xx=-w/2+(c+.5)*w/cols;let wm=kind==='business'?M.glass:(Math.random()>.19?choose([M.glass,M.dark,M.gold]):M.plaster);box(g,xx,yy,d/2+.012,w/cols*.62,1.25,.04,wm,false);if(kind==='market'&&floor===0)box(g,xx,.35,d/2+.06,w/cols*.84,.55,.09,choose([M.red,M.teal,M.yellow]),false)}}}
function building(x,z,w,d,h,kind,index=0){const g=group(city,x,0,z);const palettes=kind==='market'?[M.brick,M.plaster,M.yellow,M.teal]:kind==='business'?[M.glass,M.blue,M.concrete]:kind==='residential'?[M.plaster,M.concrete,M.brick]:[M.plaster,M.concrete,M.teal,M.yellow];const base=choose(palettes);box(g,0,h/2,0,w,h,d,base);box(g,0,h+.25,0,w+1,.5,d+1,kind==='business'?M.dark:M.sidewalk,false);const floors=Math.max(1,Math.floor(h/3.1));windowsFor(g,w,h,d,floors,kind);if(kind==='market'){box(g,0,.8,d/2+.27,w*1.04,.18,.7,M.red,false);box(g,0,1.08,d/2+.29,w*.88,.06,.1,M.gold,false)}if(kind==='business'){for(let f=0;f<floors;f++)box(g,0,.75+f*3.1,d/2+.035,w*.91,.06,.03,M.gold,false);box(g,0,h+.55,0,w*.58,.18,d*.58,M.dark,false)}else{for(let f=0;f<Math.floor(w/4);f++)box(g,-w/2+2+f*4,.28,d/2+.05,1.25,.34,.06,choose([M.dark,M.red,M.yellow]),false)}
 if(kind==='residential'||kind==='commercial'){for(let f=0;f<Math.min(4,floors);f++)box(g,w/2+.2,1.4+f*3.1,0,.5,.13,d*.58,M.dark,false)}
 if(kind==='market'&&index%3===0){const awning=box(g,0,2.1,d/2+.75,w*1.05,.14,1.2,choose([M.red,M.teal,M.yellow]),false);}
 if(index%5===0&&kind!=='business'){box(g,0,h+.7,0,w*.18,.28,d*.2,M.dark,false)}return g;}
function makeRoundabout(x,z){const ring=new THREE.Mesh(new THREE.CylinderGeometry(9,9,.18,32),M.sidewalk);ring.position.set(x,.12,z);ring.receiveShadow=true;city.add(ring);const island=new THREE.Mesh(new THREE.CylinderGeometry(7.5,8,.35,32),M.grass);island.position.set(x,.3,z);island.castShadow=true;city.add(island);for(let i=0;i<5;i++){const a=i*Math.PI*2/5;cylinder(city,x+Math.cos(a)*3,.72,z+Math.sin(a)*3,.45,1.05,M.leaf2);const s=new THREE.Mesh(sphereGeo,M.leaf2);s.position.set(x+Math.cos(a)*3,1.65,z+Math.sin(a)*3);s.scale.set(1,1.1,1);city.add(s)}cylinder(city,x,1,z, .22,1.3,M.gold);}
function tree(x,z,scale=1){const g=group(city,x,0,z);cylinder(g,0,1.45*scale,0,.23*scale,2.9*scale,M.trunk,7);for(let i=0;i<4;i++){const s=new THREE.Mesh(sphereGeo,i%2?M.leaf:M.leaf2);s.position.set(rand(-.35,.35)*scale,(2.75+i*.35)*scale,rand(-.35,.35)*scale);s.scale.set(1.05*scale,1.15*scale,.95*scale);s.castShadow=true;g.add(s)}}
function makeDistrict(d,index){const r=d.kind==='coast'?110:86;const sizes=d.kind==='market'?[13,16,19]:d.kind==='business'?[20,26,32]:d.kind==='commercial'?[17,21,24]:[15,18,21];
 for(let k=-2;k<=2;k++){const off=k*37;if(Math.abs(off)<17)continue;localRoad(d.x+off,d.z,r*2,true,k===0?10:7);localRoad(d.x,d.z+off,r*2,false,k===0?10:7)}
 // District-specific skyline and landmark composition.
 if(d.kind==='business'){for(let i=0;i<8;i++){const x=d.x+rand(-77,77),z=d.z+rand(-70,70);building(x,z,rand(17,26),rand(17,25),rand(35,82),d.kind,i)}building(d.x-26,d.z-21,31,24,94,d.kind,20);building(d.x+29,d.z+18,24,24,72,d.kind,21);}
 else if(d.kind==='coast'){for(let i=0;i<16;i++)building(d.x+rand(-85,85),d.z+rand(-80,36),rand(11,20),rand(12,19),rand(5,15),'commercial',i);const lighthouse=group(city,d.x+55,0,d.z+24);cylinder(lighthouse,0,7,0,2.5,14,M.white,12);cylinder(lighthouse,0,14.4,0,3.2,1.5,M.red,12);cylinder(lighthouse,0,15.5,0,1.7,1,M.gold,12);for(let i=0;i<4;i++)box(lighthouse,0,7+i*2.7,2.51,.18,.55,.03,M.red,false);for(let i=0;i<14;i++)tree(d.x-100+i*14,d.z+63,rand(.7,1.1));
 for(let i=0;i<18;i++){const x=d.x-96+i*12;box(city,x,.55,d.z+52,7,1.1,2.2,i%3?M.teal:M.yellow,false);box(city,x,.8,d.z+50.8,7.2,.18,4,M.gold,false)}}
 else {for(let ix=-2;ix<=2;ix++)for(let iz=-2;iz<=2;iz++){if(Math.abs(ix)<1&&Math.abs(iz)<1)continue;const x=d.x+ix*31+rand(-4,4),z=d.z+iz*31+rand(-4,4),w=rand(...sizes),dep=rand(...sizes);let h=d.kind==='market'?rand(7,17):d.kind==='residential'?rand(10,25):rand(9,33);if(d.kind==='commercial'&&Math.abs(ix)+Math.abs(iz)<3)h=rand(22,42);building(x,z,w,dep,h,d.kind,ix*iz+ix+iz+20)}}
 if(d.kind==='commercial')makeRoundabout(d.x,d.z);
 if(d.kind==='market'){// original neighborhood mosque-inspired landmark
  const mg=group(city,d.x+35,0,d.z+24);box(mg,0,5,0,18,10,13,M.plaster);box(mg,0,10.2,0,20,.55,15,M.teal);for(const xx of [-5,0,5]){const dome=new THREE.Mesh(new THREE.SphereGeometry(2.5,12,8,0,Math.PI*2,0,Math.PI/2),M.teal);dome.position.set(xx,10.45,0);dome.scale.y=.74;dome.castShadow=true;mg.add(dome)}for(const xx of [-6,6]){cylinder(mg,xx,8,0,.55,16,M.plaster,8);const tip=new THREE.Mesh(coneGeo,M.gold);tip.position.set(xx,16.5,0);tip.scale.set(.7,1.7,.7);mg.add(tip)}for(let i=-1;i<=1;i++){const door=box(mg,i*4,2.2,6.54,2.1,4.4,.1,M.dark);const arch=new THREE.Mesh(new THREE.TorusGeometry(1.05,.11,6,12,Math.PI),M.gold);arch.position.set(i*4,4.4,6.6);mg.add(arch)} }
 if(d.kind==='residential'){for(let i=0;i<5;i++)tree(d.x-68+i*32,d.z+53,rand(.7,1.05));}
 // sidewalks and corner lamps animate later
 for(let i=-1;i<=1;i++)for(let j=-1;j<=1;j++){if(i===0&&j===0)continue;sidewalkStrip(d.x+i*58,d.z+j*58,10,10)}
}
districts.forEach(makeDistrict);

