districts.forEach(makeDistrict);

// A small bus station, tea stalls, traffic, and people give every district a different rhythm.
function makeLamp(x,z){const g=group(city,x,0,z);cylinder(g,.0,2.1,0,.09,4.2,M.dark,7);box(g,.42,4.05,0,.95,.12,.17,M.gold,false);const bulb=new THREE.Mesh(sphereGeo,new THREE.MeshBasicMaterial({color:'#ffe1a3'}));bulb.position.set(.82,3.98,0);bulb.scale.set(.18,.16,.18);g.add(bulb)}
for(const d of districts){for(let i=0;i<5;i++){const a=i*1.7;makeLamp(d.x+Math.cos(a)*53,d.z+Math.sin(a)*53)}if(d.kind==='market'||d.kind==='commercial'){for(let i=0;i<4;i++){const x=d.x+rand(-23,23),z=d.z+rand(-24,24);box(city,x,.65,z,3.8,1.3,2.2,choose([M.teal,M.red,M.yellow]),false);box(city,x,.6,z,4.1,.12,2.5,M.dark,false)}}}
// Simple animated people: colorful, locally grounded silhouettes at a small mobile-friendly count.
const walkers=[];const outfitMats=['#283a42','#6e5346','#d2c19a','#55716b','#9a5945','#475568','#c0a76e','#d8d1c0'].map(c=>mat(c));
function makePerson(x,z,isPlayer=false,index=0){const g=group(scene,x,0,z);const skin=mat(choose(['#875d49','#a8765b','#c08a68']));const clothes=isPlayer?mat('#2d6159'):outfitMats[index%outfitMats.length];const legMat=mat(isPlayer?'#283c3b':'#3e4140');const torso= new THREE.Mesh(new THREE.CapsuleGeometry(.34,.72,3,7),clothes);torso.position.y=1.42;torso.castShadow=true;g.add(torso);const head=new THREE.Mesh(sphereGeo,skin);head.position.y=2.12;head.scale.set(.27,.34,.28);head.castShadow=true;g.add(head);const hair=new THREE.Mesh(sphereGeo,mat(isPlayer?'#282622':'#282522'));hair.position.set(0,2.31,-.025);hair.scale.set(.28,.18,.29);hair.castShadow=true;g.add(hair);const legs=[];for(const side of [-1,1]){const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.12,.58,2,6),legMat);leg.position.set(side*.16,.55,0);leg.castShadow=true;g.add(leg);legs.push(leg)}
 if(isPlayer){const scarf=box(g,0,1.76,.29,.4,.13,.06,M.gold,false);scarf.rotation.z=-.1}
 return {g,legs,phase:Math.random()*5,isPlayer,targetX:x,targetZ:z,skin,clothes};}
const player=makePerson(0,5,true);player.g.rotation.y=Math.PI;
for(let i=0;i<30;i++){const d=choose(districts.slice(0,4));const p=makePerson(d.x+rand(-35,35),d.z+rand(-32,32),false,i);p.speed=rand(.45,1.25);p.targetX=p.g.position.x+rand(-13,13);p.targetZ=p.g.position.z+rand(-13,13);walkers.push(p)}
const cars=[];const carMats=['#bd8e60','#536d73','#a74537','#d3c6a9','#d3a548','#45545c'].map(c=>mat(c,.35,.28));
function makeCar(x,z,color,scale=1,type='car'){const g=group(scene,x,0,z);const body=box(g,0,.79,0,type==='bus'?2.1:1.75,.65,type==='bus'?5.4:3.3,color);const cabin=box(g,0,1.4,-.14,type==='bus'?1.8:1.43,.72,type==='bus'?3.2:1.85,type==='bus'?M.yellow:M.glass);if(type==='cng'){body.scale.set(1.3,.55,1.7);cabin.scale.set(1.22,.72,1.05);box(g,0,1.48,.5,1.35,.72,.07,M.dark,false);box(g,0,1.48,.57,.6,.72,.06,M.teal,false)}if(type==='rickshaw'){body.scale.set(.9,.38,1.15);cabin.scale.set(.88,.9,.09,M.teal);cabin.position.set(0,1.55,-.55);const canopy=box(g,0,2.18,-.55,1.5,.13,1.5,M.red);}
 const wheelmat=mat('#202827');for(const sx of [-.9,.9])for(const sz of [-1.1,1.1]){const w=new THREE.Mesh(new THREE.CylinderGeometry(.31,.31,.16,10),wheelmat);w.rotation.z=Math.PI/2;w.position.set(sx,.38,sz);g.add(w)}for(const sx of [-.53,.53]){const lamp=box(g,sx,.82,1.68,.22,.17,.035,M.gold,false);lamp.material=new THREE.MeshBasicMaterial({color:'#ffe6ad'})}
 if(type==='bus'){for(let i=0;i<5;i++)box(g,-.94,1.62,-1.3+i*.55,.04,.35,.32,M.glass,false);for(let i=0;i<5;i++)box(g,.94,1.62,-1.3+i*.55,.04,.35,.32,M.glass,false)}
 g.scale.setScalar(scale);scene.add(g);return {g,speed:rand(3,5),phase:rand(0,Math.PI*2),type};}
const trafficTypes=['car','car','cng','bus','rickshaw'];for(let i=0;i<12;i++){const d=choose(districts.slice(0,4));const t=choose(trafficTypes);const c=makeCar(d.x+rand(-54,54),d.z+rand(-54,54),t==='cng'?mat('#388379'):t==='rickshaw'?mat('#ae5447'):choose(carMats),t==='bus'?.9:t==='rickshaw'?.7:1,t);cars.push(c)}
// Five original landmarks create a gentle sightseeing loop instead of a combat objective.
const discoveries=districts.map((d,i)=>({district:d,seen:false,position:new THREE.Vector3(d.x+(i===2?35:0),0,d.z+(i===2?24:0))}));

