// Soft landmark markers are visible in-world but intentionally feel like part of the city.
const markers=[];for(const item of discoveries){const g=group(scene,item.position.x,0,item.position.z);const halo=new THREE.Mesh(new THREE.RingGeometry(1.8,2.1,28),new THREE.MeshBasicMaterial({color:'#e4c890',transparent:true,opacity:.8,side:THREE.DoubleSide}));halo.rotation.x=-Math.PI/2;halo.position.y=.12;g.add(halo);const dot=new THREE.Mesh(sphereGeo,new THREE.MeshBasicMaterial({color:'#f5dcae'}));dot.position.y=2.3;dot.scale.set(.12,.12,.12);g.add(dot);const stem=box(g,0,1.1,0,.025,1.8,.025,M.gold,false);markers.push({g,halo,dot,item})}
const keys=new Set();let movingTouch={x:0,y:0},touchRun=false,jumpUntil=0,driving=null,driveSpeed=0,cameraYaw=.22,cameraPitch=.16,cameraDistance=20,drag=null,lastTime=0,elapsed=0,toastTimer=0,weatherIndex=0,weatherNames=['Clear','Light rain','Cloudy'];
const shell=document.querySelector('#game-shell'),interaction=document.querySelector('#interaction'),interactionLabel=document.querySelector('#interaction-label'),toast=document.querySelector('#toast');
const showToast=text=>{toast.textContent=text;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2800)};
function worldToMap(){// Landmark-anchored interpolation keeps the tiny guide geographically legible.
 let px=0,py=0,total=0;for(const d of districts){const dist=Math.hypot((player.g.position.x-d.x)/175,(player.g.position.z-d.z)/190);const w=1/(.045+dist*dist*dist*dist);const xy={ 'Agrabad':[48,46],'GEC Circle':[90,88],'Chawkbazar':[155,95],'Muradpur':[151,47],'Patenga':[57,134]}[d.name];px+=xy[0]*w;py+=xy[1]*w;total+=w}return [px/total,py/total]}
function refreshMap(){const [x,y]=worldToMap();document.querySelector('#map-player').setAttribute('cx',x);document.querySelector('#map-player').setAttribute('cy',y);document.querySelector('#map-player-halo').setAttribute('cx',x);document.querySelector('#map-player-halo').setAttribute('cy',y)}
function currentDistrict(){let near=districts[0],distance=Infinity;for(const d of districts){const q=Math.hypot(player.g.position.x-d.x,player.g.position.z-d.z);if(q<distance){distance=q;near=d}}return distance<145?near:null}
function rotateCityMarkers(){for(const el of document.querySelectorAll('.map-place'))el.classList.toggle('active',el.dataset.place===currentDistrict()?.name)}
function doDiscover(item){if(item.seen)return;item.seen=true;const n=discoveries.filter(d=>d.seen).length;document.querySelector('#discover-count').textContent=`${n} / 5`;document.querySelector('#progress-fill').style.width=`${n*20}%`;item.seen=true;const marker=markers.find(m=>m.item===item);marker.halo.material.color.set('#aac6a4');marker.halo.material.opacity=.35;showToast(`A note from ${item.district.name} added to your city guide.`);document.querySelector('.nearby-note span:last-child').textContent=item.district.note;}
let targetDiscovery=null,targetCar=null;
function closestCar(){let best=null,dist=Infinity;for(const c of cars){const d=c.g.position.distanceTo(player.g.position);if(d<dist){dist=d;best=c}}return dist<5.4?best:null}
function syncPrompt(){let dBest=null,distance=Infinity;for(const d of discoveries)if(!d.seen){const q=player.g.position.distanceTo(d.position);if(q<distance){dBest=d;distance=q}}targetDiscovery=distance<9?dBest:null;targetCar=closestCar();if(driving){interaction.classList.add('visible');interactionLabel.textContent='E  Leave vehicle';return}if(targetDiscovery){interaction.classList.add('visible');interactionLabel.textContent=`Explore ${targetDiscovery.district.name}`}else if(targetCar){interaction.classList.add('visible');interactionLabel.textContent=targetCar.type==='rickshaw'?'Take a cycle rickshaw':targetCar.type==='cng'?'Ride the CNG':'Get in and drive'}else interaction.classList.remove('visible')}
function interact(){if(driving){player.g.position.copy(driving.g.position);player.g.position.x+=2.7;player.g.position.y=0;player.g.visible=true;driving=null;driveSpeed=0;showToast('Back on foot. The city is yours.');return}if(targetDiscovery){doDiscover(targetDiscovery);return}if(targetCar){driving=targetCar;player.g.visible=false;driveSpeed=0;showToast('Easy on the accelerator. Explore at your own pace.');return}showToast('Wander a little. Your city guide is just around the corner.')}
function hop(){if(!driving&&player.g.position.y<.03){jumpUntil=performance.now()+430;player.g.position.y=2.2}}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys.add(k);if(k==='e')interact();if(k===' '||k==='spacebar')hop();if(k==='m')toggleMap()});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
function toggleMap(force){const open=force??!shell.classList.contains('map-open');shell.classList.toggle('map-open',open)}
document.querySelector('#map-toggle').addEventListener('click',()=>toggleMap(true));document.querySelector('#map-close').addEventListener('click',()=>toggleMap(false));
document.querySelector('#map-overlay-places').innerHTML=districts.map((d,i)=>`<button data-index="${i}"><small>${String(i+1).padStart(2,'0')} · ${d.desc}</small><b>${d.name}</b><span>${d.note}</span></button>`).join('');document.querySelectorAll('#map-overlay-places button').forEach(button=>button.addEventListener('click',()=>{const d=districts[+button.dataset.index];player.g.position.set(d.x,0,d.z+8);player.g.visible=true;driving=null;toggleMap(false);showToast(`A new afternoon in ${d.name}.`)}));
// Dragging anywhere on the world gives a gentle, orbit-style third-person camera.
canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;drag={x:e.clientX,y:e.clientY,id:e.pointerId};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;cameraYaw-=(e.clientX-drag.x)*.004;cameraPitch=THREE.MathUtils.clamp(cameraPitch+(e.clientY-drag.y)*.002,-.04,.55);drag.x=e.clientX;drag.y=e.clientY});canvas.addEventListener('pointerup',()=>drag=null);canvas.addEventListener('wheel',e=>{cameraDistance=THREE.MathUtils.clamp(cameraDistance+e.deltaY*.012,9,34)},{passive:true});
// Touch joystick and action controls are generously sized for phones and tablets.
const joystick=document.querySelector('#joystick'),knob=document.querySelector('#joy-knob');let joyPointer=null;joystick.addEventListener('pointerdown',e=>{joyPointer=e.pointerId;joystick.setPointerCapture(e.pointerId);updateJoy(e)});joystick.addEventListener('pointermove',e=>{if(joyPointer===e.pointerId)updateJoy(e)});const releaseJoy=()=>{joyPointer=null;movingTouch={x:0,y:0};knob.style.transform='translate(0,0)'};joystick.addEventListener('pointerup',releaseJoy);joystick.addEventListener('pointercancel',releaseJoy);function updateJoy(e){const r=joystick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),max=33,n=Math.min(1,len/max);movingTouch={x:len?dx/len*n:0,y:len?dy/len*n:0};knob.style.transform=`translate(${movingTouch.x*max}px,${movingTouch.y*max}px)`}
document.querySelector('#touch-run').addEventListener('pointerdown',e=>{e.preventDefault();touchRun=true});['pointerup','pointercancel','pointerleave'].forEach(ev=>document.querySelector('#touch-run').addEventListener(ev,()=>touchRun=false));document.querySelector('#touch-interact').addEventListener('pointerdown',e=>{e.preventDefault();interact()});
// Rain is a lightweight GPU-friendly particle field; the sun and sky shift with it.
const rainGeo=new THREE.BufferGeometry(),rainCount=520,rainPositions=new Float32Array(rainCount*3);for(let i=0;i<rainCount;i++){rainPositions[i*3]=rand(-105,105);rainPositions[i*3+1]=rand(8,78);rainPositions[i*3+2]=rand(-105,105)}rainGeo.setAttribute('position',new THREE.BufferAttribute(rainPositions,3));const rain=new THREE.Points(rainGeo,new THREE.PointsMaterial({color:'#c6d9db',size:.105,transparent:true,opacity:.63,depthWrite:false}));rain.visible=false;scene.add(rain);
document.querySelector('#weather-btn').addEventListener('click',()=>{weatherIndex=(weatherIndex+1)%3;const state=weatherNames[weatherIndex];document.querySelector('#weather-btn').innerHTML=`${weatherIndex===1?'☂':weatherIndex===2?'☁':'☀'} <span>${state}</span>`;document.querySelector('#weather-label').textContent=weatherIndex===1?'COASTAL DRIZZLE':weatherIndex===2?'CLOUDY SKIES':'GOLDEN HOUR';document.querySelector('#weather-icon').textContent=weatherIndex===1?'☂':weatherIndex===2?'☁':'☀';rain.visible=weatherIndex===1;sun.intensity=weatherIndex===1?1.35:weatherIndex===2?2.1:3.15;scene.fog.color.set(weatherIndex===1?'#819394':weatherIndex===2?'#9ca9a8':'#a9b5b2');scene.background.set(weatherIndex===1?'#819394':weatherIndex===2?'#9ca9a8':'#a9b5b2');showToast(weatherIndex===1?'A little rain is rolling in from the bay.':weatherIndex===2?'Clouds gather over the port.':'The late sun breaks through.')});
document.querySelector('#sound-btn').addEventListener('click',e=>{e.currentTarget.classList.toggle('muted');e.currentTarget.textContent=e.currentTarget.classList.contains('muted')?'♪':'♫';showToast(e.currentTarget.classList.contains('muted')?'Ambient sound muted.':'Ambient sound enabled.')});

